traps.trap02.txt:
	If ($Event <> 50) @end;	
	
//	Say("系统消息：发生事件6.1，强盗密谋");
//	Say("系统消息：Event 的值变为 51，进入战斗");
//	Say("系统消息：发生事件6.2，引发机关，劝说入伙");
//	Say("系统消息：Event 的值变为 55，再次进入战斗");
//	Say("系统消息：战斗胜利，事件6结束，Event 的值变为 60");

	StopMusic();
	SetNpcDeathScript("杨影枫","主角死亡.txt");
	DisableNpcAI();
	LoadNpc("qiangdao.npc");
	SetNpcActionFile("龙寨主", 0, "npc023_强盗头子坐着.asf");
	SetNpcActionFile("龙寨主", 1, "npc023_强盗头子坐着.asf");
	SetNpcActionFile("龙寨主", 11, "npc023_强盗头子浓烟.asf");
	PlayerRunTo(11, 63);
	MoveScreen(5, 220, 1);

	Say("黑风寨主：事情办得怎么样？", 48);
	Say("强盗阿非：老大，小的已经打听清楚了，那商人张仲天确实带着武功秘笈《武道德经》，本来小的们就要得手了，哪知突然半路杀出个毛头小子，小的们不敌，所以……。", 66);
	Say("黑风寨主：废物！带头大哥交待下来的事情，居然给我办砸了，你不是给老子丢脸吗？！", 48);
	Say("强盗阿木：老大，你那摧金断玉的铁沙掌在江南也是赫赫有名的，那小子竟然敢抢我们的买卖，简直是老虎头上想拔毛！老大，你可得给小的们讨个公道啊！"，50);
	Say("黑风寨主：哼！老子在江湖上混了这么多年，对付一个张仲天和一个乳臭未干的臭小子，那还不是易如反掌？不过……那小子的武功是不是很厉害呀？", 48);
	Say("探子：老大武功盖世，神勇无双，还怕那小子！只不过，张仲天有那小子保护，这样正面交锋，兄弟们难免会有损伤，我有一计，不费吹灰之力，便可一箭双雕！", 49);
	Say("黑风寨主：哦？少卖关子，赶快说来。", 48);
	Say("探子：小的可扮成店小二，伺机在其饮食中下迷魂药，那时……", 49);
	Say("黑风寨主：妙计！事若能成，我必重重有赏！", 48);
	Say("杨影枫：哈哈哈！果然好计，阁下真是智比诸葛呀！", 3);
	Say("黑风寨主：什么人？！", 48);

	SetNpcActionFile("龙寨主", 0, "npc023_st.asf");
	SetNpcActionFile("龙寨主", 1, "npc023_pst.asf");
	NpcSpecialAction("龙寨主", "npc023_强盗头子跳起.asf");
	Sleep(1000);
	SetPlayerScn();
	PlayerRunTo(16, 52);
    SetPlayerDir(5);
	Say("强盗阿非：老大，他就是挡我们财路的那个小子！", 66);
	Say("杨影枫：不错，就是小爷我，哼，你们想行凶抢劫，遇上了小爷，算你们倒霉！",	8);
	Say("黑风寨主：好小子，竟敢跟你爷爷我作对，是不是活得不耐烦了？兄弟们，给我砍！", 48);
	PlayMusic("mc027.mp3");
	AddToMemo(90080);
	SetPlayerState(1);
	EnableFight();
	EnableNpcAI();
	Assign($Event, 51);
	
@end:
	Return;
